def shape(s):
 b=s.BoundingBox();return {'valid':s.isValid(),'solids':len(s.Solids()),'faces':len(s.Faces()),'envelope_mm':[b.xlen,b.ylen,b.zlen]}
def render(s,path,axis='z'):
 v,tr=s.tessellate(.45);v=np.array([[x.x,x.y,x.z] for x in v]);fig=plt.figure(figsize=(7,4));ax=fig.add_axes([0,0,1,1],projection='3d');ax.add_collection3d(Poly3DCollection(v[np.array(tr)],facecolors='#b0d0e1',edgecolors='#5d7180',linewidths=.05));ax.auto_scale_xyz(*v.T);ax.set_box_aspect(np.maximum(np.ptp(v,axis=0),1),zoom=1.3);ax.view_init(25,-60,vertical_axis=axis);ax.set_axis_off();fig.savefig(path,dpi=170);plt.close(fig)
